/**
 * Initializes a DataTable for the CollectionsTable with various configurations and event handlers.
 *
 * @param {Object} layer - The layer object containing database and name properties.
 * @param {string} layer.database - The name of the database.
 * @param {string} layer.name - The name of the layer.
 */
function initCollectionsTable(layer) {
  // Initialize DataTable for CollectionsTable
  collectionsTable = $('#CollectionsTable').DataTable({
    // AJAX configuration for fetching data from the server
    ajax: {
      url: global_stratos_url + '/api/databases/' + layer.database + '/layers/' + layer.name + '/collections',
      dataSrc: function (response) {
        // Set total number of records and store table data
        _this.SetTotal(response.data.length);
        tableData = response.data;
        return response.data; // Return the data to be displayed in the table
      },
      error: function (response) {
        // Display an error message if the AJAX request fails
        cw_Stratos_Nav.ShowErrorBox(response.responseJSON.message);
      }
    },

    // Set the row ID to the 'collection' property
    rowId: 'collection',

    // Define table columns with their respective data, titles, and custom renderers
    columns: [
      {
        data: "collection",
        title: "Collection",
        className: "dt-center"
      },
      {
        data: "title",
        title: "Title"
      },
      {
        data: "physicalCount",
        title: "# Sources",
        className: "dt-center",
        render: _this.FormatCount // Custom renderer for physicalCount column
      },
      {
        data: "count",
        title: "Registered",
        className: "dt-center",
        render: _this.FormatNumSources // Custom renderer for count column
      },
      {
        data: "status",
        title: "Availability",
        className: "dt-center",
        render: _this.FormatAvailability // Custom renderer for status column
      },
      {
        data: "type",
        title: "Type"
      },
      {
        data: "path",
        title: "Location",
        render: _this.FormatPath // Custom renderer for path column
      }
    ],

    // Single row selection configuration
    select: {
      style: "single",
      className: 'row-selected'
    },

    // Set scrollY based on available height in the content area
    scrollY: $('.content').innerHeight() - $('.page-header-content').innerHeight() + 3 - $('#footer').innerHeight() - $('.page-header-content').innerHeight() + "px",

    // Enable scrolling and other DataTable features
    scroller: true,
    deferRender: true,
    lengthChange: false,
    responsive: true,
    processing: true,
    stateSave: true,
    scrollCollapse: false,

    // Customize the DOM layout
    dom: 'lrti',

    // Callback function executed once the DataTable is fully initialized
    initComplete: function (settings, json) {
      // Deselect all rows when the table is initialized
      collectionsTable.rows().deselect();
      console.log('deselecting rows');
