1. Calculate the total number of elements in the two-dimensional array, which is n × n.
2. Allocate memory for the two-dimensional array by calling calloc() with the calculated number of elements and the size of each element (which is sizeof(datatype)).
3. Cast the returned pointer to a two-dimensional array of the desired datatype.

Here's an example code snippet that demonstrates this:
```c
#include <stdio.h>
#include <stdlib.h>

int main() {
    int n = 5; // replace with your desired size

    // Calculate the total number of elements
    size_t num_elements = n * n;

    // Allocate memory for the two-dimensional array
    int *two_d_array = (int *)calloc(num_elements, sizeof(int));

    // Check if memory allocation was successful
    if (two_d_array == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return 1;
    }

    // Cast the pointer to a two-dimensional array and access elements
    int (*arr)[n] = (int (*)[n])two_d_array;

    // Access elements using arr[i][j] syntax
    for (size_t i = 0; i < n; i++) {
        for (size_t j = 0; j < n; j++) {
            arr[i][j] = i * n + j;
        }
    }

    // Print the allocated memory
    for (size_t i = 0; i < n; i++) {
        for (size_t j = 0; j < n; j++) {
            printf("%d ", arr[i][j]);
        }
        printf("\n");
    }

    // Free the allocated memory
    free(two_d_array);

    return 0;
}
```
In this example, we first calculate the total number of elements in the two-dimensional array and allocate memory using calloc(). We then cast the returned pointer to a two-dimensional array of integers and access elements using the arr[i][j] syntax. Finally, we free the allocated memory using free().
