        'password' => 'your-database-password',
    ],
];
```

 12. Create an `index.php` file to bootstrap the application.

```php
<?php

require_once __DIR__ . '/vendor/autoload.php';

$config = require __DIR__ . '/config.php';

$sqsClient = new SQSClient($config['aws']['region'], $config['aws']['accessKey'], $config['aws']['secretKey']);
$sqsSubscriber = new SQSSubscriber($sqsClient, new DatabaseHandler(new DatabaseConnection($config['database']['host'], $config['database']['port'], $config['database']['dbname'], $config['database']['username'], $config['database']['password'])));

// Subscribe to the SQS queue
$sqsSubscriber->subscribeToQueue('your-sqs-topic-url');
