<?php

namespace AmazonSQSSubscriber;

use AmazonSQSSubscriber\SQSSubscriber\SQSSubscriber;
use AmazonSQSSubscriber\SQSClient\SQSClient;

class SQSSubscriber
{
    private $sqsClient;
    private $databaseHandler;

    public function __construct(SQSClient $sqsClient, DatabaseHandler $databaseHandler)
    {
        $this->sqsClient = $sqsClient;
        $this->databaseHandler = $databaseHandler;
    }

    public function subscribeToQueue($queueUrl)
    {
